//! ntfy priority for an incident severity.

use bsc_incident::Severity;

/// ntfy priority for a severity: `Info`→1 … `Critical`→5. Critical is the one that buzzes through
/// Do-Not-Disturb, which is exactly the line between "worth a glance later" and "look now".
pub fn priority_for(sev: Severity) -> u8 {
    match sev {
        Severity::Info => 1,
        Severity::Low => 2,
        Severity::Medium => 3,
        Severity::High => 4,
        Severity::Critical => 5,
    }
}
